using namespace std;
static const string certdir="certs/", state=".tls-private/";
static mutex grantMutex;
static void fail(const string& s){throw runtime_error(s);}
static void ensureDir(const string& s){if(mkdir(s.c_str(),0700)<0 && errno!=EEXIST)fail("No se pudo crear "+s);}
static bool exists(const string& s){return access(s.c_str(),F_OK)==0;}
static void writeFile(const string& s,const string& v,bool privateFile=false){ofstream f(s.c_str(),ios::binary|ios::trunc);if(!f)fail("No se puede escribir "+s);f<<v;f.close();if(privateFile)chmod(s.c_str(),0600);}
static string bioString(BIO* b){char* p=nullptr;long n=BIO_get_mem_data(b,&p);return string(p,(size_t)n);}
static string hex(const unsigned char* p,size_t n){static const char* h="0123456789abcdef";string s;for(size_t i=0;i<n;i++){s+=h[p[i]>>4];s+=h[p[i]&15];}return s;}
static string digest(const string& s){unsigned char h[SHA256_DIGEST_LENGTH];SHA256((const unsigned char*)s.data(),s.size(),h);return hex(h,sizeof(h));}
static string token(){unsigned char b[32];if(RAND_bytes(b,sizeof(b))!=1)fail("RAND_bytes");return hex(b,sizeof(b));}
static bool validId(const string& s){if(s.size()<4||s.size()>50||s.substr(0,3)!="SI-")return false;for(char c:s)if(!isalnum((unsigned char)c)&&c!='-'&&c!='_')return false;return true;}
static EVP_PKEY* makeKey(){EVP_PKEY_CTX* ctx=EVP_PKEY_CTX_new_id(EVP_PKEY_RSA,nullptr);if(!ctx)fail("EVP_PKEY_CTX");EVP_PKEY* key=nullptr;if(EVP_PKEY_keygen_init(ctx)<=0||EVP_PKEY_CTX_set_rsa_keygen_bits(ctx,3072)<=0||EVP_PKEY_keygen(ctx,&key)<=0)fail("keygen");EVP_PKEY_CTX_free(ctx);return key;}
static string keyPem(EVP_PKEY* key){BIO* b=BIO_new(BIO_s_mem());if(!PEM_write_bio_PrivateKey(b,key,nullptr,nullptr,0,nullptr,nullptr))fail("write key");string s=bioString(b);BIO_free(b);return s;}
static EVP_PKEY* loadKey(const string& s){FILE* f=fopen(s.c_str(),"r");if(!f)fail("key file "+s);EVP_PKEY* k=PEM_read_PrivateKey(f,nullptr,nullptr,nullptr);fclose(f);if(!k)fail("invalid key "+s);return k;}
static X509* loadCert(const string& s){FILE* f=fopen(s.c_str(),"r");if(!f)fail("cert file "+s);X509* x=PEM_read_X509(f,nullptr,nullptr,nullptr);fclose(f);if(!x)fail("invalid cert "+s);return x;}
static string certPem(X509* x){BIO* b=BIO_new(BIO_s_mem());if(!PEM_write_bio_X509(b,x))fail("write cert");string s=bioString(b);BIO_free(b);return s;}
static void addExt(X509* cert,X509* issuer,int nid,const string& value){X509V3_CTX ctx;X509V3_set_ctx(&ctx,issuer,cert,nullptr,nullptr,0);X509_EXTENSION* ext=X509V3_EXT_conf_nid(nullptr,&ctx,nid,(char*)value.c_str());if(!ext)fail("extension "+value);X509_add_ext(cert,ext,-1);X509_EXTENSION_free(ext);}
static void setCN(X509_NAME* name,const string& cn){if(!X509_NAME_add_entry_by_txt(name,"CN",MBSTRING_ASC,(const unsigned char*)cn.c_str(),-1,-1,0))fail("CN");}
static X509* makeCert(EVP_PKEY* subjectKey,const string& name,X509* issuer,EVP_PKEY* signingKey,bool ca,int days){X509* x=X509_new();if(!x)fail("X509_new");X509_set_version(x,2);unsigned char serial[16];RAND_bytes(serial,sizeof(serial));BIGNUM* bn=BN_bin2bn(serial,sizeof(serial),nullptr);ASN1_INTEGER* sn=BN_to_ASN1_INTEGER(bn,nullptr);X509_set_serialNumber(x,sn);ASN1_INTEGER_free(sn);BN_free(bn);X509_gmtime_adj(X509_get_notBefore(x),-60);X509_gmtime_adj(X509_get_notAfter(x),days*86400L);X509_set_pubkey(x,subjectKey);X509_NAME* sub=X509_get_subject_name(x);setCN(sub,name);X509_set_issuer_name(x,issuer?X509_get_subject_name(issuer):sub);addExt(x,issuer?issuer:x,NID_basic_constraints,ca?"critical,CA:TRUE":"critical,CA:FALSE");addExt(x,issuer?issuer:x,NID_key_usage,ca?"critical,keyCertSign,cRLSign":"critical,digitalSignature,keyEncipherment");if(!ca){addExt(x,issuer,NID_ext_key_usage,"serverAuth,clientAuth");addExt(x,issuer,NID_subject_alt_name,"DNS:"+name);}if(!X509_sign(x,signingKey,EVP_sha256()))fail("X509_sign");return x;}
static string makeCSR(EVP_PKEY* key,const string& id){X509_REQ* r=X509_REQ_new();X509_REQ_set_version(r,0);X509_NAME* name=X509_REQ_get_subject_name(r);setCN(name,id);X509_REQ_set_pubkey(r,key);if(!X509_REQ_sign(r,key,EVP_sha256()))fail("sign CSR");BIO* b=BIO_new(BIO_s_mem());PEM_write_bio_X509_REQ(b,r);string s=bioString(b);BIO_free(b);X509_REQ_free(r);return s;}
static string signCSR(const string& csr,const string& id){BIO* b=BIO_new_mem_buf(csr.data(),(int)csr.size());X509_REQ* r=PEM_read_bio_X509_REQ(b,nullptr,nullptr,nullptr);BIO_free(b);if(!r)fail("CSR invalida");char cn[128]={};X509_NAME_get_text_by_NID(X509_REQ_get_subject_name(r),NID_commonName,cn,sizeof(cn));EVP_PKEY* pub=X509_REQ_get_pubkey(r);if(id!=cn||!pub||X509_REQ_verify(r,pub)!=1)fail("CSR no corresponde a ID");EVP_PKEY* caKey=loadKey(state+"ca.key");X509* ca=loadCert(certdir+"siqp-trust.crt");X509* crt=makeCert(pub,id,ca,caKey,false,90);string pem=certPem(crt);X509_free(crt);X509_free(ca);EVP_PKEY_free(caKey);EVP_PKEY_free(pub);X509_REQ_free(r);return pem;}
static void init(bool migrate){ensureDir(certdir);ensureDir(state);if(exists(state+"ca.key")||exists(certdir+"siqp-trust.crt")){if(!migrate)fail("Certificados existentes. Para migrar usa init --migrate (respalda antes)");if(exists(state+"ca.key"))fail("Ya existe una CA; no se sobrescribe");string backup="certs-backup-"+to_string(time(nullptr));ensureDir(backup);for(const char* f:{"server.crt","server.key","siqp-trust.crt"})if(exists(certdir+f))rename((certdir+f).c_str(),(backup+"/"+f).c_str());cout<<"Certificados anteriores en "<<backup<<"\n";}EVP_PKEY* caKey=makeKey();X509* ca=makeCert(caKey,"TicAmazon-CA",nullptr,caKey,true,1825);writeFile(state+"ca.key",keyPem(caKey),true);writeFile(certdir+"siqp-trust.crt",certPem(ca));EVP_PKEY* serverKey=makeKey();X509* server=makeCert(serverKey,"INT-01",ca,caKey,false,365);writeFile(certdir+"server.key",keyPem(serverKey),true);writeFile(certdir+"server.crt",certPem(server));writeFile(state+"tokens.txt", "",true);EVP_PKEY_free(caKey);EVP_PKEY_free(serverKey);X509_free(ca);X509_free(server);cout<<"CA e intermediario INT-01 creados en C++. Publica solo certs/siqp-trust.crt.\n";}
struct Grant{string hash;long expires;};
static map<string,Grant> loadGrants(){map<string,Grant> m;ifstream f((state+"tokens.txt").c_str());string id,hash;long expiry;while(f>>id>>hash>>expiry)m[id]={hash,expiry};return m;}
static void saveGrants(const map<string,Grant>& m){stringstream ss;for(auto& e:m)ss<<e.first<<" "<<e.second.hash<<" "<<e.second.expires<<"\n";writeFile(state+"tokens.txt",ss.str(),true);}
static void issue(const string& id){if(!validId(id))fail("ID invalido");if(!exists(state+"ca.key"))fail("Primero init");lock_guard<mutex> lock(grantMutex);auto m=loadGrants();string t=token();m[id]={digest(t),time(nullptr)+900};saveGrants(m);cout<<"Token de "<<id<<" (15 minutos, un solo uso): "<<t<<"\n";}
static int connectTcp(const string& host,const string& port){addrinfo hints={},*res=nullptr;hints.ai_socktype=SOCK_STREAM;hints.ai_family=AF_UNSPEC;if(getaddrinfo(host.c_str(),port.c_str(),&hints,&res))fail("DNS/host invalido");int fd=-1;for(auto p=res;p;p=p->ai_next){fd=socket(p->ai_family,p->ai_socktype,p->ai_protocol);if(fd>=0&&connect(fd,p->ai_addr,p->ai_addrlen)==0)break;if(fd>=0)close(fd);fd=-1;}freeaddrinfo(res);if(fd<0)fail("No se pudo conectar a "+host+":"+port);return fd;}
static int listenTcp(const string& port){int fd=socket(AF_INET,SOCK_STREAM,0);if(fd<0)fail("socket");int one=1;setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in a={};a.sin_family=AF_INET;a.sin_addr.s_addr=INADDR_ANY;a.sin_port=htons(stoi(port));if(bind(fd,(sockaddr*)&a,sizeof(a))<0||listen(fd,20)<0)fail("bind/listen "+port);return fd;}
static void sendMessage(SSL* ssl,const string& s){if(s.size()>16384)fail("Mensaje demasiado grande");uint32_t len=htonl((uint32_t)s.size());auto sendAll=[&](const char* p,size_t n){while(n){int k=SSL_write(ssl,p,(int)n);if(k<=0)fail("SSL_write");p+=k;n-=k;}};sendAll((const char*)&len,4);sendAll(s.data(),s.size());}
static string recvMessage(SSL* ssl){auto readAll=[&](char* p,size_t n){while(n){int k=SSL_read(ssl,p,(int)n);if(k<=0)fail("SSL_read");p+=k;n-=k;}};uint32_t len;readAll((char*)&len,4);len=ntohl(len);if(len>16384||len==0)fail("Mensaje demasiado grande");string s(len,'\0');readAll(&s[0],len);return s;}
static SSL_CTX* serverContext(){SSL_CTX* ctx=SSL_CTX_new(TLS_server_method());SSL_CTX_set_min_proto_version(ctx,TLS1_2_VERSION);if(SSL_CTX_use_certificate_file(ctx,(certdir+"server.crt").c_str(),SSL_FILETYPE_PEM)!=1||SSL_CTX_use_PrivateKey_file(ctx,(certdir+"server.key").c_str(),SSL_FILETYPE_PEM)!=1)fail("Certificado del intermediario invalido");return ctx;}
static SSL_CTX* clientContext(){SSL_CTX* ctx=SSL_CTX_new(TLS_client_method());SSL_CTX_set_min_proto_version(ctx,TLS1_2_VERSION);if(SSL_CTX_load_verify_locations(ctx,(certdir+"siqp-trust.crt").c_str(),nullptr)!=1)fail("Falta CA publica");SSL_CTX_set_verify(ctx,SSL_VERIFY_PEER,nullptr);return ctx;}
static void serve(const string& port){if(!exists(state+"ca.key"))fail("Primero init");SSL_CTX* ctx=serverContext();int fd=listenTcp(port);cout<<"Servicio de alta TLS C++ escuchando en "<<port<<"\n";while(true){int c=accept(fd,nullptr,nullptr);if(c<0)continue;thread([ctx,c](){SSL* ssl=SSL_new(ctx);SSL_set_fd(ssl,c);try{if(SSL_accept(ssl)!=1)fail("Handshake TLS");string id=recvMessage(ssl),tok=recvMessage(ssl),csr=recvMessage(ssl);if(!validId(id)||tok.size()>128||csr.size()>8192)fail("Solicitud invalida");string result;{lock_guard<mutex> lock(grantMutex);auto grants=loadGrants();auto it=grants.find(id);string h=digest(tok);if(it==grants.end()||it->second.expires<time(nullptr)||it->second.hash.size()!=h.size()||CRYPTO_memcmp(it->second.hash.data(),h.data(),h.size())!=0)fail("Token invalido o caducado");result=signCSR(csr,id);grants.erase(it);saveGrants(grants);}sendMessage(ssl,"OK");sendMessage(ssl,result);cout<<"Alta autorizada: "<<id<<"\n";}catch(const exception& e){cerr<<"Alta rechazada: "<<e.what()<<"\n";try{sendMessage(ssl,"ERROR");}catch(...){}}SSL_shutdown(ssl);SSL_free(ssl);close(c);}).detach();}}
static void enroll(const string& id,const string& host,const string& port){if(!validId(id))fail("ID invalido");ensureDir(certdir);string keyPath=certdir+id+".key",crtPath=certdir+id+".crt";if(exists(keyPath)&&exists(crtPath)){cout<<"Certificado existente: "<<crtPath<<"\n";return;}if(exists(keyPath)||exists(crtPath))fail("Certificado o clave incompletos; revisar");if(!exists(certdir+"siqp-trust.crt"))fail("Falta certificado publico de CA");string t;const char* env=getenv("SIQP_ENROLL_TOKEN");if(env)t=env;else{cout<<"Token de incorporacion: "<<flush;getline(cin,t);}EVP_PKEY* key=makeKey();string pem=keyPem(key),csr=makeCSR(key,id);EVP_PKEY_free(key);SSL_CTX* ctx=clientContext();int fd=connectTcp(host,port);SSL* ssl=SSL_new(ctx);SSL_set_fd(ssl,fd);X509_VERIFY_PARAM* param=SSL_get0_param(ssl);if(X509_VERIFY_PARAM_set1_host(param,"INT-01",0)!=1)fail("TLS host");if(SSL_connect(ssl)!=1)fail("Handshake TLS: verificar CA e identidad INT-01");sendMessage(ssl,id);sendMessage(ssl,t);sendMessage(ssl,csr);string status=recvMessage(ssl);if(status!="OK")fail("Alta rechazada por intermediario");string cert=recvMessage(ssl);BIO* b=BIO_new_mem_buf(cert.data(),(int)cert.size());X509* x=PEM_read_bio_X509(b,nullptr,nullptr,nullptr);BIO_free(b);if(!x)fail("Certificado recibido invalido");X509* ca=loadCert(certdir+"siqp-trust.crt");X509_STORE* store=X509_STORE_new();X509_STORE_add_cert(store,ca);X509_STORE_CTX* verify=X509_STORE_CTX_new();X509_STORE_CTX_init(verify,store,x,nullptr);if(X509_verify_cert(verify)!=1||X509_check_host(x,id.c_str(),id.size(),0,nullptr)!=1)fail("Certificado emitido no valido");X509_STORE_CTX_free(verify);X509_STORE_free(store);X509_free(ca);X509_free(x);writeFile(keyPath,pem,true);writeFile(crtPath,cert);SSL_shutdown(ssl);SSL_free(ssl);close(fd);SSL_CTX_free(ctx);cout<<"Identidad TLS creada: "<<id<<"\n";}
static string arg(int argc,char** argv,const string& name,const string& fallback=""){for(int i=2;i+1<argc;i++)if(argv[i]==name)return argv[i+1];return fallback;}
int main(int argc,char** argv){try{OPENSSL_init_ssl(0,nullptr);if(argc<2)fail("Uso: ./TLSManager.out init [--migrate] | issue --id SI-01 | serve [--port 9443] | enroll --id SI-01 --host IP_O_DNS [--port 9443]");string action=argv[1];if(action=="init")init(argc>2&&string(argv[2])=="--migrate");else if(action=="issue")issue(arg(argc,argv,"--id"));else if(action=="serve")serve(arg(argc,argv,"--port","9443"));else if(action=="enroll")enroll(arg(argc,argv,"--id"),arg(argc,argv,"--host"),arg(argc,argv,"--port","9443"));else fail("Accion desconocida");return 0;}catch(const exception& e){cerr<<"TLS: "<<e.what()<<"\n";return 1;}}
